const feedbackDrafts=new WeakMap();
const categoryAnswers=Array(10).fill(''),openCategories=new Set();
const categoryExamples=['Fleabag, фильмы Хичкока, Наследники','I Love Dick, Гарри Поттер, любимые авторы','Земфира, джаз, классическая музыка вживую','бег, керамика, бокс — помогает выпустить энергию','Лондон, Италия, пустой пляж','красная помада, Vivienne Westwood, винтажные зеркала','матча, рамен, свежий хлеб','Marina Abramović, Рианна, моя бабушка','придумывать проекты с нуля, разбираться, делать красиво','запах дождя, утро без спешки, старые фотографии'];
